package sprint

import (
	"fmt"
	"path/filepath"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

func ArtifactRelPath(s Sprint, stage PlanningStage) string {
	base := filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug))
	switch stage {
	case StageRequirements:
		return base + "/requirements.md"
	case StageCodeContext:
		return base + "/code-context.md"
	case StageSprintIndex:
		return base + "/sprint-index.md"
	case StageTechnicalHandbook:
		return base + "/technical-handbook.md"
	case StageAreaReasoning:
		return base + "/reasoning"
	case StageReasoning:
		return base + "/reasoning.md"
	case StagePlan:
		return base + "/plan.md"
	case StageExecute:
		return base + "/execute.md"
	case StageReview:
		return base + "/review.md"
	case StageSmoke:
		return base + "/smoke.md"
	default:
		return base
	}
}

func FlowStateRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "flow-state.json"))
}

func ExecuteRunStateRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, ".run-state.json"))
}

func ArtifactPath(root string, s Sprint, stage PlanningStage) (string, error) {
	return resolveSprintContained(root, s, ArtifactRelPath(s, stage))
}

func FlowStatePath(root string, s Sprint) (string, error) {
	return resolveSprintContained(root, s, FlowStateRelPath(s))
}

func resolveSprintContained(root string, s Sprint, rel string) (string, error) {
	if filepath.IsAbs(rel) {
		return "", fmt.Errorf("artifact path %q must be workspace-relative", rel)
	}
	cleanRel := filepath.ToSlash(filepath.Clean(filepath.FromSlash(rel)))
	if cleanRel == "." || strings.HasPrefix(cleanRel, "../") || cleanRel == ".." {
		return "", fmt.Errorf("artifact path %q escapes workspace", rel)
	}
	full, err := workspace.ResolveInside(root, cleanRel)
	if err != nil {
		return "", err
	}
	rootPath, err := workspace.ResolveInside(root, filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug)))
	if err != nil {
		return "", err
	}
	if !inside(rootPath, full) {
		return "", fmt.Errorf("artifact path %q escapes sprint root", rel)
	}
	return full, nil
}

func inside(root, candidate string) bool {
	rel, err := filepath.Rel(filepath.Clean(root), filepath.Clean(candidate))
	if err != nil {
		return false
	}
	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)))
}

package study

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
	"gopkg.in/yaml.v3"
)

func DiscoverStudies(root string) ([]Study, error) {
	studiesDir, err := workspace.ResolveInside(root, "studies")
	if err != nil {
		return nil, err
	}
	entries, err := readOptionalDir(studiesDir)
	if err != nil {
		return nil, fmt.Errorf("read studies: %w", err)
	}
	var studies []Study
	for _, entry := range entries {
		if isHidden(entry.Name()) || !entry.IsDir() {
			continue
		}
		studies = append(studies, Study{
			Name: entry.Name(),
			Path: filepath.Join(studiesDir, entry.Name()),
		})
	}
	sort.Slice(studies, func(i, j int) bool {
		return studies[i].Name < studies[j].Name
	})
	return studies, nil
}

func DiscoverSources(study Study) ([]Source, error) {
	sourcesDir := filepath.Join(study.Path, "sources")
	entries, err := readOptionalDir(sourcesDir)
	if err != nil {
		return nil, fmt.Errorf("read sources for study %q: %w", study.Name, err)
	}
	sourceMetadata, err := readLiveSourceMetadata(study)
	if err != nil {
		return nil, err
	}
	var sources []Source
	for _, entry := range entries {
		if isHidden(entry.Name()) || entry.Name() == "reports" {
			continue
		}
		if strings.HasSuffix(entry.Name(), ".ultraplan-source.yml") || strings.HasSuffix(entry.Name(), ".ultraplan-source.yaml") {
			continue
		}
		sourcePath := filepath.Join(sourcesDir, entry.Name())
		metadata := sourceMetadata[entry.Name()]
		if entry.IsDir() {
			localMetadata, err := readSourceMetadataFile(filepath.Join(sourcePath, ".ultraplan-source.yml"))
			if err != nil {
				return nil, err
			}
			metadata = mergeApplicableDimensions(localMetadata, metadata)
			sources = append(sources, Source{
				Name:                 entry.Name(),
				Kind:                 SourceKindDirectory,
				Path:                 sourcePath,
				ApplicableDimensions: metadata,
			})
			continue
		}
		if strings.ToLower(filepath.Ext(entry.Name())) != ".md" {
			continue
		}
		content, err := os.ReadFile(sourcePath)
		if err != nil {
			return nil, fmt.Errorf("read source %s: %w", sourcePath, err)
		}
		frontmatter, applicable, err := parseFrontmatter(string(content))
		if err != nil {
			return nil, fmt.Errorf("parse source %s metadata: %w", sourcePath, err)
		}
		sources = append(sources, Source{
			Name:                 entry.Name(),
			Kind:                 SourceKindMarkdown,
			Path:                 sourcePath,
			ApplicableDimensions: mergeApplicableDimensions(applicable, metadata),
